import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
let cleanup: () => void; let north: Tenant; let acme: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); north = await createTenant("n"); acme = await createTenant("a"); });
afterAll(() => cleanup());
async function ins(t: Tenant) {
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  return issueRepo.insertIssue(issueInput(t.org.id, t.project.id, {}), t.userIds.owner, n);
}
describe("tmp", () => {
  it("pages same-timestamp rows", async () => {
    vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));
    for (let i = 0; i < 9; i++) { await ins(north); await ins(acme); }
    vi.setSystemTime(new Date("2026-01-02T00:00:00Z")); await ins(north);
    vi.useRealTimers();
    const all = await issueRepo.listIssues({ orgId: north.org.id, limit: 100, cursor: null });
    for (const size of [1, 2, 3, 4, 7]) {
      const seen: string[] = []; let cursor: string | null = null;
      do { const p = await issueRepo.listIssues({ orgId: north.org.id, limit: size, cursor }); seen.push(...p.items.map((x) => x.id)); expect(p.items.every((x) => x.orgId === north.org.id)).toBe(true); cursor = p.nextCursor; } while (cursor);
      expect(seen).toEqual(all.items.map((x) => x.id));
    }
    expect(all.total).toBe(all.items.length);
  });
});
